import React from "react";
import { Link } from "react-router-dom";

import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";

// Vérifie bien le chemin de ton image (si "assets" ne marche pas → "../assets/img/bg1.png")
import HeroImage from "assets/img/bg1.png";

export default function Index() {
  return (
    <>
      <IndexNavbar fixed />

      {/* HERO avec image et overlay marron */}
      <section
        className="relative mt-16 md:mt-20 h-screen max-h-860-px flex items-center"
        style={{
          backgroundImage: `linear-gradient(rgba(107, 20, 15, 0.65), rgba(107, 20, 15, 0.25)), url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
          backgroundRepeat: "no-repeat",
        }}
      >
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-bold text-5xl md:text-7xl text-white leading-tight">
              Dalal ak jàamm,
            </h1>
            <p className="mt-6 text-2xl md:text-3xl font-light text-white max-w-xl">
              Nassour Abdel-Mahamoud !
            </p>
          </div>
        </div>
      </section>

      {/* LIGNE D’ICÔNES HORIZONTALE SUPERPOSÉE À LA FRONTIÈRE */}
      <section className="relative z-20 -mt-12 md:-mt-16">
        <div className="container mx-auto px-4">
          <div className="flex flex-wrap justify-center gap-6">
            {[
              { icon: "fas fa-bolt", title: "Rapide" },
              { icon: "fas fa-shield-alt", title: "Sécurisé" },
              { icon: "fas fa-mobile-alt", title: "Mobile First" },
              { icon: "fas fa-plug", title: "Connecté" },
            ].map((item, idx) => (
              <div
                key={idx}
                className="bg-white rounded-xl shadow-lg p-6 w-52 flex flex-col items-center"
              >
                <div className="w-14 h-14 flex items-center justify-center rounded-full bg-blueGray-50 shadow mb-4">
                  <i className={`${item.icon} text-2xl text-blueGray-600`} />
                </div>
                <h6 className="text-lg font-semibold text-blueGray-700">
                  {item.title}
                </h6>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* FEATURES */}
      <section id="features" className="py-24 bg-blueGray-50">
        <div className="container mx-auto px-4 text-center max-w-3xl">
          <h2 className="text-3xl md:text-4xl font-semibold text-blueGray-800">
            Ce que vous obtenez
          </h2>
          <p className="text-blueGray-500 mt-4">
            Un starter propre, réactif, et extensible pour présenter votre produit/service.
          </p>
        </div>
      </section>

      <Footer />
    </>
  );
}
